def transform(grid):
    h, w = len(grid), len(grid[0])
    split = None
    for c in range(1, w-1):
        if all(row[c] == grid[0][c] for row in grid) and c == w-c-1:
            split = ('v', c)
            break
    if split is None:
        for r in range(1, h-1):
            if all(v == grid[r][0] for v in grid[r]) and r == h-r-1:
                split = ('h', r)
                break
    if split is None:
        raise ValueError('separator not found')
    axis, k = split
    if axis == 'v':
        a = [row[:k] for row in grid]
        b = [row[k+1:] for row in grid]
    else:
        a, b = grid[:k], grid[k+1:]
    common = set(v for row in a for v in row) & set(v for row in b for v in row)
    if len(common) != 1:
        raise ValueError(f'expected one shared color, got {common}')
    color = next(iter(common))
    return [[3 if x == color and y == color else color for x,y in zip(ra,rb)] for ra,rb in zip(a,b)]
